## 二、文明兴衰之道：察天象、审人事、探地脉、卜天道

> “**尔来有客问曰：如何知文明之存亡？紫葳应之曰：观天象以察星辰移位，审人事以观青蚨游走，卜天道以测荧惑守心，探地脉以究黄道晦明，此皆天道之迹也**。”

### 1. **天象即趋势**
- 星辰移位象征文明重心转移；
- 荧惑逆行（火星逆行）暗喻社会动荡；
