## 二、文言浓缩的核心技巧：动词驱动 + 省略衔接

### 1. **动词为骨**
- “入”“注”“焖”“沥”等皆为文言中常见动词；
- 在现代语境下，它们代表明确的操作节点，便于AI识别执行顺序；
- 若嵌入AI指令系统，这些动词即可成为“操作关键词”。

### 2. **省略为魂**
- 不写“如果……那么……”，而是直接呈现“结果”；
- 如“过38.5则药”中省略了“体温超过38.5℃需服药”的判断逻辑；
- AI只需训练一次，便可自动补全“隐含前提”。

### 3. **数字为锚**
- “焖三”“过38.5”“反向同速”等数值提供精确触发条件；
- AI可据此设定阈值、执行判断、启动流程；
- 使文言浓缩链具备“可执行性”。

